 SearchOptions options(boolean enabled,String mode,String protocol){return new SearchOptions(enabled,mode,protocol,"",5,"basic");}
 @Test public void routingAndToolsIsolation()throws Exception{ChatApiClient c=new ChatApiClient();JSONArray h=new JSONArray();SearchOptions auto=options(true,"automatic","responses");assertTrue(auto.builtin);assertFalse(auto.tavily);assertEquals("",auto.key);JSONObject body=c.requestBody("fixture",h,.7,123,1,"default","responses",auto);assertEquals("web_search",body.getJSONArray("tools").getJSONObject(0).getString("type"));assertEquals("web_search_call.action.sources",body.getJSONArray("include").getString(0));assertEquals("auto",body.getString("tool_choice"));assertFalse(c.requestBody("fixture",h,.7,123,1,"default","responses",SearchOptions.OFF).has("tools"));assertFalse(c.requestBody("fixture",h,.7,123,1,"default","chat_completions",options(false,"responses","chat_completions")).has("tools"));assertTrue(options(true,"automatic","chat_completions").tavily);assertTrue(options(true,"tavily","responses").tavily);assertFalse(options(true,"tavily","responses").builtin);try{c.requestBody("fixture",h,.7,123,1,"default","chat_completions",options(true,"responses","chat_completions"));fail();}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("供应商"));}java.lang.reflect.Method legacy=ChatApiClient.class.getDeclaredMethod("requestBody",String.class,JSONArray.class,double.class,int.class,double.class,String.class,String.class);legacy.setAccessible(true);assertFalse(((JSONObject)legacy.invoke(c,"topic",h,.2,32,1,"default","responses")).has("tools"));}
 String response="{\"status\":\"completed\",\"output\":[{\"type\":\"web_search_call\",\"status\":\"completed\",\"action\":{\"sources\":[{\"url\":\"https://example.org/a\",\"title\":\"Official\"},{\"url\":\"javascript:alert(1)\"}]}},{\"type\":\"message\",\"content\":[{\"type\":\"output_text\",\"text\":\"answer\",\"annotations\":[{\"type\":\"url_citation\",\"url\":\"https://example.org/a\",\"title\":\"Official\"},{\"type\":\"url_citation\",\"url\":\"https://example.org/b\",\"title\":\"Other\"}]}]}]}";
 @Test public void sseSourcesStatusAndCanonicalText()throws Exception{String fixture="data: {\"type\":\"response.web_search_call.in_progress\"}\n\ndata: {\"type\":\"response.web_search_call.searching\"}\n\ndata: {\"type\":\"response.output_text.delta\",\"output_index\":1,\"delta\":\"answer\"}\n\ndata: {\"type\":\"response.output_text.done\",\"output_index\":1,\"text\":\"answer\"}\n\ndata: {\"type\":\"response.completed\",\"response\":"+response+"}\n\n";final String[] text={""},status={""};final int[] done={0},sources={0};new ChatApiClient().parseSse(new ByteArrayInputStream(fixture.getBytes(StandardCharsets.UTF_8)),"responses",new ChatApiClient.StreamCallback(){public void onDelta(String s){text[0]+=s;}public void onSnapshot(String s){text[0]=s;}public void onReasoning(String s){}public void onStatus(String s){}public void onDone(){done[0]++;}public void onError(String s){fail(s);}public void onSearchSources(SearchSources s,String state){sources[0]=s.items.length();status[0]=state;}});assertEquals("answer",text[0]);assertEquals(1,done[0]);assertEquals(2,sources[0]);assertEquals("内置搜索完成",status[0]);}
 @Test public void finalNonstreamSourcesAndSafeHint()throws Exception{JSONObject r=new JSONObject(response);assertEquals("answer",ChatResponseParser.parse(r,false));SearchSources s=SearchSources.fromResponse(r);assertEquals(2,s.items.length());assertEquals("Official",s.items.getJSONObject(0).getString("title"));assertEquals("",s.items.getJSONObject(1).getString("snippet"));assertTrue(ChatApiClient.searchError(400).contains("web_search"));assertFalse(ChatApiClient.searchError(400).contains("Authorization"));ResponseStream state=new ResponseStream();state.inspectSearch(r);assertTrue(state.searchCalled);state.inspectSearch(new JSONObject(response).put("status","incomplete"));assertTrue(state.searchStatus.contains("未完成"));}
 @Test public void mockHttpNonstreamAndUnsupportedNoLeak()throws Exception{mockHttp(200,response);mockHttp(400,"{\"error\":{\"message\":\"web_search unsupported; api_key=local-fixture\"}}");}
 private void mockHttp(int code,String payload)throws Exception{java.net.ServerSocket server=new java.net.ServerSocket(0,1,java.net.InetAddress.getByName("127.0.0.1"));java.util.concurrent.CountDownLatch done=new java.util.concurrent.CountDownLatch(1);final String[] request={""},answer={""},error={""};final int[] sources={0};Thread worker=new Thread(()->{try(java.net.Socket socket=server.accept()){socket.setSoTimeout(5000);request[0]=readRequest(socket);byte[] bytes=payload.getBytes(StandardCharsets.UTF_8);socket.getOutputStream().write(("HTTP/1.1 "+code+" Fixture\r\nContent-Type: application/json\r\nContent-Length: "+bytes.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));socket.getOutputStream().write(bytes);socket.getOutputStream().flush();}catch(Exception e){error[0]="mock:"+e;done.countDown();}});worker.start();ChatApiClient.CancellationHandle cancel=new ChatApiClient.CancellationHandle();try{new ChatApiClient(cancel).chat("http://127.0.0.1:"+server.getLocalPort(),"local-fixture","fixture",new JSONArray(),.7,32,1,"default","responses",options(true,"automatic","responses"),new ChatApiClient.CallbackResult<String>(){public void onSearchSources(SearchSources s,String status){sources[0]=s.items.length();}public void onSuccess(String value){answer[0]=value;done.countDown();}public void onError(String value){error[0]=value;done.countDown();}});assertTrue(done.await(8,java.util.concurrent.TimeUnit.SECONDS));assertEquals("web_search",new JSONObject(request[0]).getJSONArray("tools").getJSONObject(0).getString("type"));if(code==200){assertEquals("answer",answer[0]);assertEquals(2,sources[0]);assertEquals("",error[0]);}else{assertEquals("",answer[0]);assertTrue(error[0].contains("web_search"));assertTrue(error[0],error[0].contains("web_search unsupported"));assertFalse(error[0].contains("local-fixture"));assertFalse(error[0].contains("raw provider body"));}}finally{cancel.cancel();server.close();worker.join(6000);}}
 private String readRequest(java.net.Socket socket)throws Exception{
  InputStream input=socket.getInputStream();ByteArrayOutputStream header=new ByteArrayOutputStream();int value,last=0;
  while((value=input.read())!=-1){header.write(value);last=(last<<8)|value;if(last==0x0d0a0d0a)break;if(header.size()>16384)throw new IOException("fixture header too large");}
  int length=0;for(String line:header.toString("US-ASCII").split("\r\n"))if(line.toLowerCase(java.util.Locale.ROOT).startsWith("content-length:"))length=Integer.parseInt(line.substring(15).trim());
  if(length>2*1024*1024)throw new IOException("fixture body too large");byte[] bytes=new byte[length];int offset=0;
  while(offset<length){int n=input.read(bytes,offset,length-offset);if(n<0)throw new EOFException("incomplete fixture request");offset+=n;}return new String(bytes,StandardCharsets.UTF_8);
 }
 @Test public void sourceTitleUpgradeAndRevisionSnapshot()throws Exception{SearchSources s=SearchSources.fromResponse(new JSONObject("{\"output\":[{\"type\":\"web_search_call\",\"action\":{\"sources\":[{\"url\":\"https://example.org/a\"}]}},{\"type\":\"message\",\"content\":[{\"annotations\":[{\"type\":\"url_citation\",\"url\":\"https://example.org/a\",\"title\":\"Real title\"}]}]}]}"));assertEquals(1,s.items.length());assertEquals("Real title",s.items.getJSONObject(0).getString("title"));JSONObject session=new JSONObject().put("id","s").put("messages",new JSONArray().put(new JSONObject().put("id","u").put("user",true).put("text","query")).put(new JSONObject().put("id","a").put("user",false).put("text","answer").put("sources",s.items)));ConversationBranches.edit(new JSONArray().put(session),"s","a",null,true);ConversationBranches.select(session,0);assertEquals("Real title",session.getJSONArray("messages").getJSONObject(1).getJSONArray("sources").getJSONObject(0).getString("title"));}
